import React from "react";
import { Outlet } from "react-router-dom";
import Sidebar from "./Sidebar";
import "./AdminLayout.css";

export default function AdminLayout() {
  return (
    <div className="adminShell">
      <Sidebar />
      <main className="adminMain">
        <Outlet />
      </main>
    </div>
  );
}
